contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 firstMinSum, address firstLog, uint256 secondMinSum, address secondLog) public {
        // Lock in an initial configuration.
        c.SetMinSum(firstMinSum);
        c.SetLogFile(firstLog);
        c.Initialized();

        // Read the locked-in values through the public getters.
        uint256 minBefore = c.MinSum();
        address logBefore = address(c.Log());

        // Any later configuration attempt must revert.
        bool sumReverted;
        try c.SetMinSum(secondMinSum) {
            sumReverted = false;
        } catch {
            sumReverted = true;
        }

        bool logReverted;
        try c.SetLogFile(secondLog) {
            logReverted = false;
        } catch {
            logReverted = true;
        }

        // Both configuration setters must reject post-initialization changes,
        // and the original values must remain in place.
        assert(
            sumReverted &&
            logReverted &&
            c.MinSum() == minBefore &&
            address(c.Log()) == logBefore
        );
    }
}

